INSERT INTO `questions` (`id`, `title`, `type`, `multi`, `category_id`, `difficulty`, `score`, `analysis`, `create_time`, `update_time`, `is_deleted`) VALUES (65,'测试选择题','CHOICE',0,13,'MEDIUM',5,'数据库的数据类型','2025-07-24 10:39:22','2025-07-27 04:38:02',1),(66,'测试判断题','JUDGE',0,14,'HARD',5,'java是世界上最好的语言','2025-07-25 09:14:14','2025-07-25 09:14:14',0),(67,'选择题1222','CHOICE',1,17,'HARD',5,'选择题解析','2025-07-27 03:16:13','2025-07-27 04:37:23',1),(68,'判断题','JUDGE',0,22,'MEDIUM',5,'判断题解析！','2025-07-27 03:16:13','2025-07-27 03:17:05',0),(69,'简答题1','TEXT',0,24,'MEDIUM',5,'简答题解析！','2025-07-27 03:16:13','2025-07-27 03:17:31',0),(70,'选择题999','CHOICE',1,30,'MEDIUM',5,'89999','2025-07-27 03:16:13','2025-07-27 04:40:29',1),(71,'选择题00000','CHOICE',1,18,'EASY',5,'测试','2025-07-27 09:23:32','2025-07-27 09:23:32',0),(72,'选择题2222','CHOICE',1,19,'MEDIUM',5,'选择题解释解释解释','2025-07-27 10:28:56','2025-07-27 10:28:56',0),(73,'以下哪个是Spring框架的核心特性？','TEXT',0,1,'MEDIUM',5,'Spring框架的核心特性包括依赖注入、面向切面编程和事务管理等。','2025-07-28 09:28:42','2025-07-28 09:28:42',0),(74,'判断题哈哈','JUDGE',0,16,'MEDIUM',10,'答案正确的！','2025-07-28 09:28:42','2025-07-28 09:28:42',0),(75,'Spring框架中的依赖注入(DI)可以通过哪些方式实现？','CHOICE',1,17,'EASY',5,'Spring框架支持多种依赖注入方式，包括构造器注入、字段注入和Setter方法注入，这些都是常见的依赖注入方式。接口注入不是Spring框架中支持的依赖注入方式。','2025-07-29 08:51:12','2025-07-29 08:51:12',0),(76,'以下哪些注解用于Spring框架中声明Bean？','CHOICE',1,17,'EASY',5,'在Spring框架中，@Required、@Autowired和@Service注解都可以用来声明Bean。@Required注解用于指示必须注入一个bean，否则会抛出异常；@Autowired注解用于自动注入依赖；@Service注解用于标注服务层组件。@Qualifier注解用于指定注入的具体Bean，但本身不声明Bean。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(77,'Spring框架中的AOP（面向切面编程）支持哪些类型的切点表达式？','CHOICE',1,17,'EASY',5,'Spring框架中的AOP支持多种类型的切点表达式，包括execution表达式用于匹配方法执行，within表达式用于匹配指定类中的所有方法，this表达式用于匹配当前代理对象，以及bean表达式用于匹配特定名称的Bean。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(78,'Spring框架中的@Transactional注解默认支持哪些事务传播行为？','CHOICE',1,17,'EASY',5,'Spring框架中的@Transactional注解默认支持REQUIRED、SUPPORTS和MANDATORY三种事务传播行为。REQUIRED表示如果当前存在事务，则加入该事务；SUPPORTS表示如果当前存在事务，可以加入事务，否则以非事务方式执行；MANDATORY表示当前必须存在事务，否则抛出异常。NEVER表示当前方法不允许在事务中执行，与默认行为不同。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(79,'在Spring框架中，以下哪些注解可以用来声明组件？','CHOICE',1,17,'EASY',5,'在Spring框架中，@Component、@Service、@Repository和@Controller注解都可以用来声明组件。@Component注解用于泛指组件，@Service注解用于服务层组件，@Repository注解用于数据访问层组件，@Controller注解用于表现层组件。这些注解都可以使类成为Spring容器的Bean，从而被自动扫描和注册。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(82,'222121','JUDGE',1,17,'MEDIUM',10,'sadadadfsfs','2026-04-13 10:46:10','2026-04-13 11:17:42',1),(83,'以下222哪个是Spring框架的核心特性？','CHOICE',0,1,'MEDIUM',5,'Spring框架的核心特性包括依赖注入、面向切面编程和事务管理等。','2026-04-13 13:45:46','2026-04-13 13:45:46',0),(84,'在Java并发编程中，关于锁的使用，以下哪些说法是正确的？','CHOICE',1,16,'MEDIUM',5,'synchronized关键字创建的是可重入锁，所以选项1错误。ReentrantLock类提供了tryLock方法，可以用于尝试非阻塞地获取锁，因此选项2正确。Lock接口提供了与synchronized关键字相比更灵活的锁定机制，例如尝试非阻塞地获取锁、可中断的锁获取等，所以选项3正确。并不是所有实现了Lock接口的锁都是可重入的，例如ReadWriteLock，因此选项4错误。','2026-04-13 17:48:51','2026-04-13 17:48:51',0),(85,'关于Java中的线程池和阻塞队列，以下哪些说法是正确的？','CHOICE',1,16,'MEDIUM',5,'线程池中的线程数量是有限的，因此选项1错误。阻塞队列确实可以用于线程池中任务的排队，所以选项2正确。使用有界阻塞队列可以防止因为任务过多而导致的内存溢出，因此选项3正确。固定大小的线程池可以减少线程创建和销毁的开销，从而提高响应速度，所以选项4正确。','2026-04-13 17:48:51','2026-04-13 17:48:51',0),(86,'以下关于Java并发编程中的锁和线程池的陈述，哪些是正确的？','JUDGE',0,16,'MEDIUM',5,'在Java并发编程中，锁可以保护共享资源不被多线程同时访问，而线程池可以有效地管理线程资源，提高系统性能。','2026-04-13 17:48:51','2026-04-13 17:48:51',0),(87,'以下关于Java并发编程中的阻塞队列的陈述，哪些是错误的？','JUDGE',0,16,'MEDIUM',5,'阻塞队列在Java并发编程中用于线程间通信，它提供了线程安全的入队和出队操作，并且当队列为空时，出队操作会阻塞直到队列中有元素可用；当队列满时，入队操作会阻塞直到队列中有空间可用。因此，任何声称阻塞队列不提供这些功能的说法都是错误的。','2026-04-13 17:48:51','2026-04-13 17:48:51',0),(88,'解释Java中的锁和阻塞队列在并发编程中的作用和区别。','TEXT',0,16,'MEDIUM',5,'此题要求考生理解Java并发编程中锁和阻塞队列的基本用途和它们之间的区别。锁用于同步控制，保证数据一致性；阻塞队列用于线程间的协调，提高效率。','2026-04-13 17:48:51','2026-04-13 17:48:51',0),(89,'Spring框架中，以下哪个注解用于声明一个Bean？','CHOICE',0,18,'HARD',5,'@Service注解用于声明一个Service层的Bean，而@Autowired用于自动注入依赖，@PostConstruct用于在Bean初始化后执行的方法，@Value用于将配置文件中的值注入到Bean的字段中。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(90,'SpringBoot中的自动配置是如何实现的？','JUDGE',0,18,'HARD',5,'SpringBoot的自动配置是通过@EnableAutoConfiguration注解实现的，它会根据classpath下的jar包依赖为应用程序自动配置Bean。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(91,'SpringCloud中，Eureka和Consul都可以作为服务注册中心，以下哪些说法是正确的？','CHOICE',1,18,'HARD',5,'Eureka和Consul都是服务注册中心，Eureka由Netflix开发，Consul提供了更丰富的服务治理功能，包括服务发现和配置管理。Eureka客户端不仅限于Java环境，也有其他语言的客户端。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(92,'SpringCloud Alibaba中的Nacos可以用于哪些功能？','CHOICE',1,18,'HARD',5,'Nacos是SpringCloud Alibaba中的一个组件，主要用于服务发现和配置管理，并不提供消息队列和分布式事务管理功能。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(93,'在Spring框架中，Bean的生命周期包括哪些阶段？','TEXT',0,18,'HARD',5,'Bean的生命周期是Spring框架中的一个重要概念，它包括从Bean的创建到销毁的整个过程，涉及到多个回调接口，允许开发者在Bean的不同生命周期阶段进行自定义操作。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(94,'SpringCloud的断路器模式中，Hystrix和Resilience4j都可以作为实现方案，以下哪些说法是正确的？','CHOICE',1,18,'HARD',5,'Hystrix确实是Netflix开发的断路器框架，并且提供了线程池隔离功能。Resilience4j是SpringCloud的一个备选方案，但它并不是官方推荐的，而且Resilience4j是支持响应式编程的。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(95,'SpringBoot中的Actuator组件可以用来做什么？','JUDGE',0,18,'HARD',5,'SpringBoot中的Actuator组件提供了生产级别的功能，如健康检查、审计、应用信息和监控等，用于监控和管理SpringBoot应用程序。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(96,'在SpringCloud中，Feign客户端相比Ribbon有什么优势？','CHOICE',1,18,'HARD',5,'Feign客户端是SpringCloud中的一个声明式Web服务客户端，它简化了服务间调用的代码，并且支持负载均衡和服务降级。但是，Feign客户端本身并不减少网络请求的开销，它只是简化了调用过程。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(97,'SpringCloud Alibaba的Sentinel组件可以用于哪些场景？','CHOICE',1,18,'HARD',5,'Sentinel是SpringCloud Alibaba中的一个流量控制组件，它可以用于流量控制、熔断和服务降级等场景。配置管理不是Sentinel的功能，而是Nacos的功能。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(98,'Spring框架中的AOP（面向切面编程）主要用于解决什么问题？','JUDGE',0,18,'HARD',5,'Spring框架中的AOP主要用于解决横切关注点问题，如日志、事务、安全等，它允许开发者将这些横切关注点与业务逻辑分离，而不是解决所有编程问题。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(99,'SpringCloud的配置中心可以支持哪些配置文件格式？','CHOICE',1,18,'HARD',5,'SpringCloud的配置中心支持多种配置文件格式，包括YAML、JSON和Properties，但XML不是SpringCloud配置中心支持的格式。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(100,'Spring框架中，@Transactional注解可以用于哪些元素上？','CHOICE',1,18,'HARD',5,'@Transactional注解在Spring框架中用于声明事务管理，它可以用于方法上，但不能用于类、接口或私有方法上。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(101,'SpringCloud的Zuul组件主要用于什么功能？','JUDGE',0,18,'HARD',5,'SpringCloud的Zuul组件主要用于API网关功能，提供路由转发、过滤等功能，而不是服务发现功能，服务发现功能主要由Eureka或Consul等组件提供。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(102,'Spring框架中，以下哪些方式可以实现Bean的自动装配？','CHOICE',1,18,'HARD',5,'在Spring框架中，@Autowired、<bean>标签的autowire属性和@Resource注解都可以用于Bean的自动装配，而@Value注解用于注入配置值，不用于自动装配。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(103,'SpringCloud的Stream组件支持哪些消息中间件？','CHOICE',1,18,'HARD',5,'SpringCloud的Stream组件支持多种消息中间件，包括RabbitMQ、Kafka和ActiveMQ，但不支持Redis，Redis主要用于缓存而不是消息中间件。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(104,'Spring框架中，以下哪些注解可以用于方法级别的权限控制？','CHOICE',1,18,'HARD',5,'在Spring框架中，@PreAuthorize、@PostAuthorize和@Secured注解可以用于方法级别的权限控制，而@Transactional注解用于声明事务管理，不用于权限控制。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(105,'SpringCloud Alibaba的Nacos可以作为服务配置中心，以下哪些说法是错误的？','CHOICE',1,18,'HARD',5,'Nacos可以作为服务配置中心，支持动态推送配置变更、配置的版本控制以及配置的加密和解密。Nacos不仅限于SpringCloud环境，也支持其他微服务环境。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(106,'Spring框架中，以下哪些是Bean的作用域？','CHOICE',1,18,'HARD',5,'在Spring框架中，Bean的作用域包括singleton、prototype、request、session和application。其中singleton和prototype是最常用的两种作用域。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(107,'SpringCloud Alibaba的Sentinel可以用于实现熔断机制，以下哪些说法是错误的？','CHOICE',1,18,'HARD',5,'Sentinel是SpringCloud Alibaba中的一个流量控制组件，它支持基于响应时间、异常比例等多种熔断规则，并且支持自定义熔断规则。Sentinel既支持服务降级，也支持熔断机制。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(108,'Spring框架中，以下哪些是Bean的初始化方法？','CHOICE',1,18,'HARD',5,'在Spring框架中，Bean的初始化方法包括InitializingBean.afterPropertiesSet、自定义init-method和@PostConstruct注解的方法，而构造器不作为初始化方法，它主要用于创建Bean实例。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(109,'SpringCloud的配置中心可以动态刷新配置，以下哪些说法是正确的？','JUDGE',0,18,'HARD',5,'SpringCloud的配置中心支持动态刷新配置，这意味着当配置中心的配置发生变化时，客户端可以无需重启即可接收到最新的配置。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(110,'Spring框架中，以下哪些是Bean的销毁方法？','CHOICE',1,18,'HARD',5,'在Spring框架中，Bean的销毁方法包括DisposableBean.destroy、自定义destroy-method和@PreDestroy注解的方法，而InitializingBean.afterPropertiesSet是Bean的初始化方法，不用于销毁。','2026-04-13 17:54:20','2026-04-13 17:54:20',0),(111,'在MySQL数据库中，以下哪种类型的索引可以提高查询效率？','CHOICE',0,19,'MEDIUM',5,'B-Tree索引、Hash索引和Full-text索引是MySQL中常用的索引类型，它们可以提高查询效率。B-Tree索引是最常用的索引类型，适用于全值匹配、范围查询、前缀匹配和排序操作。Hash索引适用于等值查询，但不适用于范围查询。Full-text索引用于全文搜索。R-Tree索引主要用于空间数据索引，不适用于常规查询优化。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(112,'在设计数据库字段时，以下哪种做法是合理的？','CHOICE',0,19,'MEDIUM',5,'在设计数据库字段时，应根据数据的实际需求选择合适的数据类型。VARCHAR(255)适用于存储长度可变的字符串，INT适用于存储整数类型的数据如年龄，DATETIME适用于存储日期和时间，TEXT适用于存储大量文本数据。这些做法都是合理的，可以根据实际情况选择使用。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(113,'在MySQL中，以下哪些因素会影响索引的选择？','CHOICE',1,19,'MEDIUM',5,'在MySQL中，索引的选择受到多种因素的影响，包括数据类型、列的大小、列的基数、查询条件和表的行数。数据类型决定了索引的存储方式和查询效率；列的大小影响索引的存储空间和查询速度；列的基数影响索引的选择性，基数越高，索引越有效；查询条件决定了索引是否被使用；表的行数影响索引的扫描效率。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(114,'在MySQL中，以下哪些操作可以优化SQL查询？','CHOICE',1,19,'MEDIUM',5,'在MySQL中，优化SQL查询的方法包括使用索引、避免使用SELECT *、使用JOIN代替子查询、使用LIMIT限制结果集大小。使用索引可以提高查询效率；避免使用SELECT *可以减少数据传输量；使用JOIN代替子查询可以减少查询次数；使用LIMIT可以限制结果集大小，提高查询速度。而使用复杂的WHERE条件可能会降低查询效率，因此不是优化SQL查询的有效方法。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(115,'在MySQL数据库中，以下哪种字段设计是不合理的？','CHOICE',0,19,'MEDIUM',5,'在MySQL数据库中，字段设计应根据实际需求选择合适的数据类型和长度。使用VARCHAR(255)存储用户昵称是合理的，因为用户昵称的长度可变；使用INT存储用户ID也是合理的，因为用户ID通常是整数；使用DATE存储用户生日也是合理的，因为生日只包含日期信息；使用DECIMAL(10,2)存储金额也是合理的，因为金额需要精确到小数点后两位。而使用CHAR(10)存储用户手机号是不合理的，因为CHAR是固定长度的字符串，而手机号长度固定为11位，使用CHAR会浪费存储空间，应该使用VARCHAR存储手机号。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(116,'在MySQL数据库中，以下哪些因素会影响索引的性能？','CHOICE',1,19,'MEDIUM',5,'在MySQL数据库中，影响索引性能的因素包括索引的类型、索引的顺序、索引的覆盖度、索引的基数和表的行数。索引的类型决定了索引的存储方式和查询效率；索引的顺序影响索引的扫描顺序；索引的覆盖度影响索引是否可以覆盖查询条件；索引的基数影响索引的选择性，基数越高，索引越有效；表的行数影响索引的扫描效率。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(117,'在MySQL数据库中，以下哪些操作可以减少索引的维护开销？','CHOICE',1,19,'MEDIUM',5,'在MySQL数据库中，减少索引的维护开销的方法包括避免频繁的UPDATE和DELETE操作、使用批量操作代替单条操作、使用索引覆盖扫描。频繁的UPDATE和DELETE操作会增加索引的维护开销；使用批量操作可以减少索引的维护次数；使用索引覆盖扫描可以减少索引的维护开销。而增加索引的数量会增加索引的维护开销，因此不是减少索引维护开销的有效方法。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(118,'在MySQL数据库中，以下哪些字段设计是合理的？','CHOICE',1,19,'MEDIUM',5,'在MySQL数据库中，合理的字段设计应根据实际需求选择合适的数据类型和长度。使用VARCHAR(255)存储用户姓名是合理的，因为用户姓名的长度可变；使用INT存储用户年龄也是合理的，因为年龄通常是整数；使用DATETIME存储用户注册时间也是合理的，因为注册时间包含日期和时间信息；使用ENUM存储用户性别也是合理的，因为性别只有有限的几种取值；使用TEXT存储用户简介也是合理的，因为用户简介可能包含大量文本数据。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(119,'在MySQL数据库中，以下哪些因素会影响SQL查询的执行计划？','CHOICE',1,19,'MEDIUM',5,'在MySQL数据库中，影响SQL查询执行计划的因素包括索引的存在、表的行数、查询条件的复杂度、数据库的版本和服务器的配置。索引的存在会影响查询是否使用索引；表的行数影响查询的扫描效率；查询条件的复杂度影响查询的执行路径；数据库的版本和服务器的配置也会影响查询的执行效率。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(120,'在MySQL数据库中，以下哪些操作可以提高查询效率？','CHOICE',1,19,'MEDIUM',5,'在MySQL数据库中，提高查询效率的方法包括使用索引、避免使用子查询、使用JOIN代替子查询、使用LIMIT限制结果集大小。使用索引可以提高查询效率；避免使用子查询可以减少查询次数；使用JOIN代替子查询可以减少查询次数；使用LIMIT可以限制结果集大小，提高查询速度。而使用复杂的WHERE条件可能会降低查询效率，因此不是提高查询效率的有效方法。','2026-04-13 18:34:54','2026-04-13 18:34:54',0),(121,'SpringAI是一个开源的人工智能框架吗？','JUDGE',0,18,'MEDIUM',5,'SpringAI不是一个开源的人工智能框架，而是一个虚构的概念。在现实中，OpenAI和Alibaba等公司或组织可能会提供人工智能相关的服务或框架，但SpringAI并不存在。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(122,'SpringAI支持哪些编程语言？','CHOICE',1,18,'MEDIUM',5,'SpringAI作为一个虚构的概念，我们假设它支持Java和Python，这两种语言在人工智能领域中非常流行。C++和JavaScript虽然也是常用的编程语言，但在这个假设中，它们不是SpringAI支持的语言。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(123,'SpringAI是否提供了自然语言处理（NLP）的功能？','JUDGE',0,18,'MEDIUM',5,'假设SpringAI是一个全面的人工智能框架，那么它很可能提供了自然语言处理（NLP）的功能，这是现代AI框架的常见特性之一。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(124,'SpringAI与Alibaba的关系是什么？','CHOICE',0,18,'MEDIUM',5,'SpringAI是一个虚构的概念，而Alibaba是一个真实存在的公司，提供各种技术和服务。它们之间没有直接的关系，因为SpringAI并不存在。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(125,'SpringAI是否支持机器学习模型的训练和部署？','JUDGE',0,18,'MEDIUM',5,'假设SpringAI是一个人工智能框架，那么它很可能支持机器学习模型的训练和部署，这是AI框架的基本功能之一。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(126,'SpringAI是否提供了云服务？','JUDGE',0,18,'MEDIUM',5,'SpringAI作为一个虚构的概念，我们假设它不提供云服务。在现实中，许多AI框架和公司会提供云服务，但在这个假设中，SpringAI不包括这一功能。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(127,'SpringAI支持哪些类型的机器学习算法？','CHOICE',1,18,'MEDIUM',5,'假设SpringAI是一个全面的人工智能框架，它可能支持多种类型的机器学习算法，包括监督学习、无监督学习和强化学习算法。遗传算法虽然也是一种算法，但在这个假设中，它不是SpringAI支持的算法类型之一。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(128,'SpringAI是否提供了API接口供开发者使用？','JUDGE',0,18,'MEDIUM',5,'假设SpringAI是一个人工智能框架，那么它很可能提供了API接口供开发者使用，以便开发者可以轻松地集成和使用其功能。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(129,'SpringAI是否与OpenAI有直接的竞争关系？','JUDGE',0,18,'MEDIUM',5,'SpringAI是一个虚构的概念，而OpenAI是一个真实存在的研究实验室，致力于创建安全和有益的通用人工智能。由于SpringAI不存在，它们之间没有直接的竞争关系。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(130,'简述SpringAI的主要特点。','TEXT',0,18,'MEDIUM',5,'这个简答题要求回答者描述SpringAI的主要特点，虽然SpringAI是虚构的，但这个题目可以帮助考察对人工智能框架一般特点的理解。','2026-04-13 18:37:03','2026-04-13 18:37:03',0),(131,'MyBatis中配置数据源时，以下哪些是常用的数据库连接池？','CHOICE',1,17,'MEDIUM',5,'MyBatis支持多种数据库连接池，其中HikariCP、DBCP和C3P0是常用的数据库连接池。HikariCP是性能最好的连接池，DBCP是Apache提供的连接池，C3P0是一个成熟的连接池实现。Tomcat JDBC是Tomcat服务器提供的连接池，不是MyBatis常用的连接池。','2026-04-13 18:40:18','2026-04-13 18:40:18',0),(132,'MyBatis Plus中，以下哪些配置是用于优化性能的？','CHOICE',1,17,'MEDIUM',5,'MyBatis Plus提供了多种性能优化配置。配置乐观锁可以减少锁竞争，提高并发性能；使用分页插件可以减少数据库查询的数据量，提高查询效率；开启二级缓存可以减少数据库访问次数，提高性能。而使用XML配置文件是MyBatis的基本配置方式，与性能优化关系不大。','2026-04-13 18:40:18','2026-04-13 18:40:18',0),(133,'在MyBatis中，以下哪些配置项是用于数据库连接的？','CHOICE',0,17,'MEDIUM',5,'在MyBatis配置文件中，driver、url、username和password是用于配置数据库连接的必要参数，分别代表数据库驱动类、数据库连接URL、数据库用户名和密码。而mapperLocations是用于指定MyBatis Mapper文件位置的配置项，与数据库连接无关。','2026-04-13 18:40:18','2026-04-13 18:40:18',0),(134,'MyBatis中，以下哪些配置可以提高SQL执行效率？','CHOICE',1,17,'MEDIUM',5,'在MyBatis中，使用预编译语句可以减少SQL解析和编译的时间，提高执行效率；开启缓存可以减少数据库访问次数，提高性能；使用批处理可以减少网络往返，提高批量操作的效率。而使用注解方式编写SQL只是MyBatis提供的一种SQL编写方式，与SQL执行效率关系不大。','2026-04-13 18:40:18','2026-04-13 18:40:18',0),(135,'MyBatis配置文件中，以下哪些元素用于配置事务管理？','CHOICE',1,17,'MEDIUM',5,'在MyBatis配置文件中，transactionManager元素用于配置事务管理器，是事务管理的核心配置。dataSource元素用于配置数据源，mapper元素用于配置Mapper文件，settings元素用于配置MyBatis全局参数，它们都与事务管理无关。','2026-04-13 18:40:18','2026-04-13 18:40:18',0),(136,'王者荣耀中，以下哪个英雄属于坦克类型？','CHOICE',0,34,'MEDIUM',5,'程咬金是王者荣耀中的坦克英雄，以其高生存能力和控制技能而闻名。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(137,'王者荣耀中，以下哪个装备最适合射手英雄？','CHOICE',0,34,'MEDIUM',5,'无尽战刃是增加物理攻击和暴击率的装备，非常适合射手英雄使用。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(138,'在王者荣耀中，以下哪个技能是露娜的大招？','CHOICE',0,34,'MEDIUM',5,'露娜的大招是月光之舞，这是一个可以进行位移和造成伤害的技能。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(139,'王者荣耀中，以下哪个英雄的技能可以对敌人造成真实伤害？','CHOICE',0,34,'MEDIUM',5,'吕布的技能可以对敌人造成真实伤害，无视敌人的防御。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(140,'在王者荣耀中，以下哪个英雄的技能可以提供视野？','CHOICE',0,34,'MEDIUM',5,'百里守约的技能可以放置视野装置，为团队提供视野。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(141,'在王者荣耀中，以下哪些英雄属于法师类型？','CHOICE',1,34,'MEDIUM',5,'妲己和王昭君都是王者荣耀中的法师英雄，以法术伤害为主。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(142,'在王者荣耀中，以下哪个装备可以增加英雄的移动速度？','CHOICE',0,34,'MEDIUM',5,'影忍之足是增加英雄移动速度的装备之一。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(143,'王者荣耀中，以下哪个英雄的技能可以对敌人造成减速效果？','CHOICE',0,34,'MEDIUM',5,'孙尚香的技能可以对敌人造成减速效果，增加追击或逃跑的能力。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(144,'在王者荣耀中，以下哪个英雄的技能可以提高自身的攻击速度？','CHOICE',0,34,'MEDIUM',5,'后羿的技能可以提高自身的攻击速度，增强输出能力。','2026-04-14 09:08:05','2026-04-14 09:08:05',0),(145,'王者荣耀中，以下哪个英雄的技能可以治疗队友？','CHOICE',0,34,'MEDIUM',5,'蔡文姬的技能可以治疗队友，是团队中的重要辅助角色。','2026-04-14 09:08:05','2026-04-14 09:08:05',0);
